class Solution {public:long long solve(string text){vector<pair<char,long long>> frames;long long total=0;for(char c:text){if(c=='('||c=='['||c=='{')frames.push_back({c,0});else{if(frames.empty())return -1;auto frame=frames.back();frames.pop_back();char expected=frame.first=='('?')':frame.first=='['?']':'}';if(c!=expected)return -1;long long value=frame.second==0?(frame.first=='('?1:frame.first=='['?2:3):2*frame.second;if(frames.empty())total+=value;else frames.back().second+=value;}}return frames.empty()?total:-1;}};